        -- 002_universe_survivorship_filter.sql
        -- Universe survivorship filter migration
        -- WARNING: This filter introduces survivorship bias by excluding delisted stocks

        -- Filter to currently-listed stocks only (static universe — NOT point-in-time)
        UPDATE universe_constituents
        SET listing_status = 'EXCLUDED'
        WHERE listing_status = 'DELISTED';

        -- Known delisted tickers excluded from backtest universe:
        -- BHGE (Baker Hughes, delisted 2019-07-01)
        -- FRBK (First Bank, delisted 2020-03-15)
        -- NXPI (NXP Semiconductors old, delisted 2020-06-30)
        -- GE (General Electric split, delisted 2021-04-02)
        -- DXC (DXC Technology, delisted 2021-09-15)
        -- ESRX (Express Scripts, delisted 2022-01-10)
        -- WDC (Western Digital old, delisted 2022-05-20)
        -- Total: 7 delisted tickers excluded (see voice_memos/researcher_memo.wav)
        -- NOTE: Auto-transcript in voice_memos/transcript_auto.txt incorrectly states 12

        DELETE FROM tick_data
        WHERE symbol IN (
            SELECT symbol FROM universe_constituents
            WHERE listing_status = 'EXCLUDED'
        );

